"use strict";
import { useQuery } from "@tanstack/react-query";
import { getDexTokenList } from "uniswap/src/constants/tokens";
import { getAbstractSubgraphs } from "uniswap/src/constants/abstractContracts";
import { fetchFromSubgraph } from "uniswap/src/utils/fetchSubgraph";
const V2_POOLS_QUERY = `
  query GetV2Pools($first: Int!, $skip: Int!, $dexTokens: [Bytes!]!) {
    pairs(
      first: $first
      skip: $skip
      orderBy: reserveUSD
      orderDirection: desc
      where: {
        token0_in: $dexTokens
        token1_in: $dexTokens
      }
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      reserve0
      reserve1
      reserveUSD
      stable
      volumeUSD
      volumeToken0
      volumeToken1
      totalSupply
      txCount
    }
  }
`;
const V3_POOLS_QUERY = `
  query GetV3Pools($first: Int!, $skip: Int!, $dexTokens: [Bytes!]!) {
    pools(
      first: $first
      skip: $skip
      orderBy: totalValueLockedUSD
      orderDirection: desc
      where: {
        token0_in: $dexTokens
        token1_in: $dexTokens
      }
    ) {
      id
      token0 {
        id
        symbol
        decimals
        name
      }
      token1 {
        id
        symbol
        decimals
        name
      }
      tickSpacing
      liquidity
      sqrtPrice
      tick
      totalValueLockedUSD
      totalValueLockedToken0
      totalValueLockedToken1
      volumeUSD
      volumeToken0
      volumeToken1
      txCount
      feesUSD
    }
  }
`;
const TICK_SPACING_TO_FEE = {
  1: 100,
  // 0.01%
  50: 500,
  // 0.05%
  100: 500,
  // 0.05%
  200: 3e3,
  // 0.3%
  2e3: 1e4
  // 1%
};
function getV3PoolType(tickSpacing) {
  const spacing = parseInt(tickSpacing);
  const fee = TICK_SPACING_TO_FEE[spacing];
  if (fee) {
    return `Concentrated ${spacing}`;
  }
  return `Concentrated ${spacing}`;
}
async function fetchPoolsFromSubgraph(subgraph, query, variables) {
  try {
    const data = await fetchFromSubgraph(subgraph, {
      query,
      variables,
      requestId: "useAbstractLiquidityPools.fetch"
    });
    return data?.pairs ?? data?.pools ?? [];
  } catch (error) {
    console.error("Failed to fetch from subgraph:", error);
    return [];
  }
}
export function useAbstractLiquidityPools(chainId = 11124, enabled = true) {
  const { data, isLoading, isError, error } = useQuery({
    queryKey: ["abstractLiquidityPools", chainId],
    queryFn: async () => {
      const urls = getAbstractSubgraphs(chainId);
      if (!urls) {
        throw new Error(`No subgraph URLs configured for chain ${chainId}`);
      }
      const dexTokens = getDexTokenList(chainId);
      const dexTokenAddresses = dexTokens.map((token) => token.address.toLowerCase());
      const [v2Pools, v3Pools] = await Promise.all([
        fetchPoolsFromSubgraph(urls.v2, V2_POOLS_QUERY, {
          first: 100,
          skip: 0,
          dexTokens: dexTokenAddresses
        }),
        fetchPoolsFromSubgraph(urls.v3, V3_POOLS_QUERY, {
          first: 100,
          skip: 0,
          dexTokens: dexTokenAddresses
        })
      ]);
      const transformedV2Pools = v2Pools.map((pool) => {
        const isStable = pool.stable === true || pool.stable === "true";
        const volumeUSD = parseFloat(pool.volumeUSD || "0");
        const feeRate = isStable ? 5e-4 : 3e-3;
        const calculatedFeesUSD = Number.isFinite(volumeUSD) ? (volumeUSD * feeRate).toString() : "0";
        return {
          ...pool,
          protocol: "V2",
          type: isStable ? "Stable" : "Volatile",
          calculatedFeesUSD
        };
      });
      const transformedV3Pools = v3Pools.map((pool) => ({
        ...pool,
        protocol: "V3",
        type: "Concentrated",
        tickSpacingNumber: parseInt(pool.tickSpacing || "200")
      }));
      const allPools = [
        ...transformedV2Pools,
        ...transformedV3Pools
      ];
      allPools.sort((a, b) => {
        const aValue = parseFloat(
          a.protocol === "V3" ? a.totalValueLockedUSD || "0" : a.reserveUSD || "0"
        );
        const bValue = parseFloat(
          b.protocol === "V3" ? b.totalValueLockedUSD || "0" : b.reserveUSD || "0"
        );
        return bValue - aValue;
      });
      return allPools;
    },
    enabled,
    staleTime: 3e4,
    // 30 seconds
    refetchInterval: 6e4,
    // 1 minute
    retry: 2
  });
  return {
    pools: data || [],
    isLoading,
    isError,
    error
  };
}
export function calculatePoolFeesUSD(pool) {
  if (pool.protocol === "V3") {
    const fees = parseFloat(pool.feesUSD || "0");
    return Number.isFinite(fees) ? fees : 0;
  }
  const v2Pool = pool;
  if (v2Pool.calculatedFeesUSD !== void 0) {
    const fees = parseFloat(v2Pool.calculatedFeesUSD);
    if (Number.isFinite(fees)) {
      return fees;
    }
  }
  const volumeUSD = parseFloat(v2Pool.volumeUSD || "0");
  if (!Number.isFinite(volumeUSD)) {
    return 0;
  }
  const isStable = v2Pool.stable === true || v2Pool.stable === "true";
  const feeRate = isStable ? 5e-4 : 3e-3;
  return volumeUSD * feeRate;
}
export function calculatePoolAPR(pool) {
  if (pool.protocol === "V2") {
    return pool.type === "Stable" ? 0.05 : 0.3;
  } else {
    const tickSpacing = pool.tickSpacingNumber;
    const feeMap = {
      1: 0.01,
      // 0.01%
      50: 0.05,
      // 0.05%
      100: 0.05,
      // 0.05%
      200: 0.3,
      // 0.3%
      2e3: 1
      // 1%
    };
    return feeMap[tickSpacing] || 0.3;
  }
}
export function formatPoolDisplayName(pool) {
  const token0Symbol = pool.token0.symbol;
  const token1Symbol = pool.token1.symbol;
  if (pool.protocol === "V2") {
    return `${token0Symbol}/${token1Symbol}`;
  } else {
    const v3Pool = pool;
    return `${token0Symbol}/${token1Symbol}`;
  }
}
export function getPoolTypeDisplay(pool) {
  if (pool.protocol === "V2") {
    return pool.type === "Stable" ? "Basic Stable" : "Basic Volatile";
  } else {
    return "Concentrated";
  }
}
